    ],
    "missing_context": [
      {
        "item": "growth_gib_per_hour",
        "why": "To determine the time-to-exhaustion and prioritize response speed.",
        "how_to_check": "Check Prometheus/Grafana for rate(node_filesystem_files_free[1h])"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify and clean up old PHP session files in /var/lib/php/sessions",
        "purpose": "Free up inodes to prevent application failure.",
        "conditions": "If /var/lib/php/sessions is confirmed as the primary consumer of inodes.",
        "expected_effect": "Increase in available inodes.",
        "risks": "Deleting active sessions may log out current users.",
        "requires_approval": true,
        "verify": "df -i /",
        "rule_ids": [
          "global.safety.001",
          "linux.storage.002"
        ]
      }
