      {
        "step": "Confirm inode usage per mountpoint",
        "hypothesis": "The inode exhaustion is indeed occurring on the root filesystem.",
        "how_to_check": "df -i /"
      },
      {
        "step": "Locate directories with the highest file counts",
        "hypothesis": "A specific directory (likely /var/lib/php/sessions) contains millions of small files.",
        "how_to_check": "find / -xdev -type f | cut -d/ -f2-4 | sort | uniq -c | sort -rn | head -n 20"
      }
    ],
    "root_cause_hypotheses": [
      "Accumulation of stale PHP session files in /var/lib/php/sessions.",
      "Application or system process creating an excessive number of small temporary files."
    ],
    "dangerous_operations": [
      {
        "operation": "Recursive deletion of files in /var/lib/php/sessions",
        "why_dangerous": "Irreversible removal of data; could impact active user sessions.",
